-- LabPass seed: condition checklists and Tier 1 safety quizzes (Member B).
-- Generated from quiz-and-checklists.ts. Run after A's seed has created the resources.
-- Matches resources by name; a resource that doesn't exist yet is skipped.
begin;

-- Checklists
update public.resources set checklist = '["Projector and screen working","Chairs and tables arranged","Whiteboard clean, markers present","No damage or litter"]'::jsonb where name = 'Seminar room';
update public.resources set checklist = '["Workbenches clear","Tools returned to their racks","Power supplies switched off","No damage to kits or benches"]'::jsonb where name = 'Robotics lab';
update public.resources set checklist = '["Powers on and self-test passes","Both probes present and undamaged","Screen free of cracks","Power cable intact"]'::jsonb where name = 'Oscilloscope';
update public.resources set checklist = '["Body and lens free of scratches","Battery charged and present","Memory card present","Lens cap and strap present"]'::jsonb where name = 'DSLR';
update public.resources set checklist = '["Build plate clean","Nozzle not clogged","Filament spool loaded and sufficient","Enclosure and frame undamaged"]'::jsonb where name = '3D printer';
update public.resources set checklist = '["Supervisor present and co-signing","Extraction fan running","Lens and bed clean","Emergency stop tested","Only approved materials loaded"]'::jsonb where name = 'Laser cutter';

-- Quizzes (one per Tier 1 resource; pass mark is a percentage, 80 = 4 of 5)
insert into public.quizzes(resource_id, questions, pass_mark)
select id, '[{"id":"q1","text":"Before using any equipment, what should you do first?","options":["Start it and see if it works","Check its condition and complete the check-in checklist","Ask a friend to hold it","Skip the checklist if you are in a hurry"],"answer":"Check its condition and complete the check-in checklist"},{"id":"q2","text":"You notice a frayed power cable at check-in. What do you do?","options":["Use it carefully","Tape it and continue","Do not use it; report an issue with a photo","Return it later without saying anything"],"answer":"Do not use it; report an issue with a photo"},{"id":"q3","text":"Who may operate Tier 3 equipment such as the laser cutter?","options":["Any student","Only students with a confirmed staff or peer supervisor present","Anyone who has watched a video","Students with more than 5 credits"],"answer":"Only students with a confirmed staff or peer supervisor present"},{"id":"q4","text":"You will be 20 minutes late to return a booking. What should you do?","options":["Nothing, it is only 20 minutes","Return it whenever convenient","Contact the lab manager and return it as soon as possible","Give it to another student to return"],"answer":"Contact the lab manager and return it as soon as possible"},{"id":"q5","text":"Something breaks while you are using it. What is the right step?","options":["Stop, make it safe, and report the incident with photos","Hide the damage","Try to repair it yourself","Keep using it if it still works"],"answer":"Stop, make it safe, and report the incident with photos"}]'::jsonb, 80 from public.resources where name = 'Oscilloscope'
on conflict (resource_id) do update set questions = excluded.questions, pass_mark = excluded.pass_mark;
insert into public.quizzes(resource_id, questions, pass_mark)
select id, '[{"id":"q1","text":"Before using any equipment, what should you do first?","options":["Start it and see if it works","Check its condition and complete the check-in checklist","Ask a friend to hold it","Skip the checklist if you are in a hurry"],"answer":"Check its condition and complete the check-in checklist"},{"id":"q2","text":"You notice a frayed power cable at check-in. What do you do?","options":["Use it carefully","Tape it and continue","Do not use it; report an issue with a photo","Return it later without saying anything"],"answer":"Do not use it; report an issue with a photo"},{"id":"q3","text":"Who may operate Tier 3 equipment such as the laser cutter?","options":["Any student","Only students with a confirmed staff or peer supervisor present","Anyone who has watched a video","Students with more than 5 credits"],"answer":"Only students with a confirmed staff or peer supervisor present"},{"id":"q4","text":"You will be 20 minutes late to return a booking. What should you do?","options":["Nothing, it is only 20 minutes","Return it whenever convenient","Contact the lab manager and return it as soon as possible","Give it to another student to return"],"answer":"Contact the lab manager and return it as soon as possible"},{"id":"q5","text":"Something breaks while you are using it. What is the right step?","options":["Stop, make it safe, and report the incident with photos","Hide the damage","Try to repair it yourself","Keep using it if it still works"],"answer":"Stop, make it safe, and report the incident with photos"}]'::jsonb, 80 from public.resources where name = 'DSLR'
on conflict (resource_id) do update set questions = excluded.questions, pass_mark = excluded.pass_mark;
